PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?item ?itemLabel ?bdate
WITH {
SELECT (GROUP_CONCAT(?num; separator="|") AS ?primes) { ?prime wdt:[property:instance of] wd:[entity:prime number] ; wdt:[property:numeric value] ?num FILTER(?num < 2021) }
} AS %primes
{
INCLUDE %primes
?item wdt:[property:occupation] wd:[entity:mathematician] .
?item wdt:[property:date of birth] ?bdate FILTER(REGEX(STR(?bdate), CONCAT("^(", ?primes, ")-"))) .
?item wikibase:sitelinks ?sitelinks .
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY DESC(?sitelinks)

