PREFIX p: <http://www.wikidata.org/prop/>
PREFIX psv: <http://www.wikidata.org/prop/statement/value/>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?child ?childLabel ?motherLabel ?date ?causeLabel WHERE {
{
SELECT ?child ?mother ?date ?cause WHERE {
?child wdt:[property:instance of] wd:[entity:human];
p:[property:date of birth]/psv:[property:date of birth] [ wikibase:timeValue ?date; wikibase:timePrecision 11 ].
?mother wdt:[property:instance of] wd:[entity:human];
p:[property:date of death]/psv:[property:date of death] [ wikibase:timeValue ?date; wikibase:timePrecision 11 ].
?child wdt:[property:mother] ?mother.
OPTIONAL { ?mother wdt:[property:cause of death] ?cause. }
}
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?date

query:
