PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?creditLabel ?item ?itemLabel ?itemDescription ?typeLabel ?series ?seriesLabel (MIN(?date) as ?date_)
WHERE
{
{ ?item wdt:[property:screenwriter] wd:[entity:Donald P. Bellisario] . BIND ( wd:[entity:screenwriter] as ?credit ) }
UNION { ?item wdt:[property:director] wd:[entity:Donald P. Bellisario] . BIND ( wd:[entity:film director] as ?credit ) }
OPTIONAL { ?item wdt:[property:instance of] ?type }
OPTIONAL { ?item wdt:[property:part of the series] ?series }
OPTIONAL { ?item wdt:[property:director]7 ?date }
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?item ?itemLabel ?itemDescription ?typeLabel ?series ?seriesLabel ?creditLabel
ORDER BY (!BOUND(?date_)) DESC(?date_)

query:
