?p p:P39 ?s. ?s ps:P39 wd:Q77685926; pq:P4100 ?group
OPTIONAL {?p wdt:P2002 ?tw}
SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} ORDER BY ?groupLabel ?pLabel

