query:
SELECT ?companyLabel (GROUP_CONCAT(DISTINCT ?founderLabel; separator=", ") AS ?founders) WHERE {
?company wdt:P112 ?founder;
wdt:P17 wd:Q30.
FILTER EXISTS { ?company wdt:P414|wdt:P249 []. }
?founder (wdt:P22|wdt:P25)?/wdt:P19 ?placeOfBirth.
MINUS { ?placeOfBirth wdt:P17 wd:Q30. }
OPTIONAL { ?founder rdfs:label ?founderLabel. FILTER(LANG(?founderLabel) = "en"). }
OPTIONAL { ?company wdt:P2403|wdt:P2137|wdt:P2139|wdt:P2226|wdt:P2295 ?money. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?companyLabel
ORDER BY DESC(MAX(?money)) ?companyLabel

annotated:
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT ?companyLabel (GROUP_CONCAT(DISTINCT ?founderLabel; separator=", ") AS ?founders) WHERE {
?company wdt:[property:founded by] ?founder;
wdt:[property:country] wd:[entity:United States of America].
FILTER EXISTS { ?company wdt:[property:stock exchange]|wdt:[property:ticker symbol] []. }
?founder (wdt:[property:father]|wdt:[property:mother])?/wdt:[property:place of birth] ?placeOfBirth.
MINUS { ?placeOfBirth wdt:[property:country] wd:[entity:United States of America]. }
OPTIONAL { ?founder rdfs:label ?founderLabel. FILTER(LANG(?founderLabel) = "en"). }
OPTIONAL { ?company wdt:[property:total assets]|wdt:[property:total equity]|wdt:[property:total revenue]|wdt:[property:market capitalization]|wdt:[property:net profit] ?money. }
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?companyLabel
ORDER BY DESC(MAX(?money)) ?companyLabel

query:
