query:
SELECT DISTINCT ?t ?value ?valueLabel ?rrLabel ?rr (SAMPLE(?image) as ?img)
WHERE
{
VALUES ?person {wd:Q1512}
{?person wdt:P570 ?death .
?person ?prop ?t FILTER (datatype(?t)=xsd:dateTime) FILTER (?t <= ?death) .
?value wikibase:directClaim ?prop. }
UNION
{
?person ?q ?statement FILTER regex (STR(?q),"prop/P") . #exclude P:describedBy
?person wdt:P570 ?death .
?statement ?p ?t FILTER regex (STR(?p), "prop/qualifier/P") FILTER (datatype(?t)=xsd:dateTime) FILTER (?t <= ?death).
?statement ?r ?value FILTER regex (STR(?r),"prop/statement/") .
BIND(IRI(CONCAT(CONCAT(SUBSTR(STR(?r),1,29),"direct/"),SUBSTR(STR(?r),40))) as ?rprop)
?rr wikibase:directClaim ?rprop .
OPTIONAL {?value wdt:P18 ?image}
}
UNION { # author of / creator of
?value wdt:P50|wdt:P98|wdt:P655|wdt:P1773|wdt:P170 ?person .
?person wdt:P570 ?death .
?value wdt:P571|wdt:P577 ?t .
FILTER (?t <= ?death)
#FILTER NOT EXISTS {?value wdt:P629 ?x }
FILTER NOT EXISTS {?person wdt:P800 ?value } .
OPTIONAL {?value wdt:P1433 ?rr .}
OPTIONAL {?value wdt:P18 ?image .}
}
UNION #Notable Works
{
?person wdt:P800 ?rr ;
wdt:P570 ?death ;
wdt:P569 ?birth .
?rr wdt:P577|wdt:P571|wdt:P1191 ?t FILTER ((?t <= ?death)&&(?t >= ?birth)).
OPTIONAL {?rr wdt:P18 ?image .}
}
UNION #discoverer or inventor
{
?rr wdt:P61 ?person .
?person wdt:P570 ?death ;
wdt:P569 ?birth .
?rr wdt:P575|wdt:P571|wdt:P585 ?t FILTER ((?t <= ?death)&&(?t >= ?birth)).
OPTIONAL {?rr wdt:P18 ?image .}
}
UNION #architect
{
?rr wdt:P84 ?person .
?person wdt:P570 ?death ;
wdt:P569 ?birth .
?rr wdt:P571|wdt:P1619 ?t FILTER ((?t <= ?death)&&(?t >= ?birth)).
OPTIONAL {?rr wdt:P18 ?image .}
}
UNION #composer
{
?rr wdt:P86 ?person .
?person wdt:P570 ?death ;
wdt:P569 ?birth .
?rr wdt:P571|wdt:P1191|wdt:P577 ?t FILTER ((?t <= ?death)&&(?t >= ?birth)).
OPTIONAL {?rr wdt:P18 ?image .}
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en, fr, de". }
} GROUP BY ?t ?value ?rr ?rrLabel ?valueLabel
ORDER BY ?t

annotated:
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>

SELECT DISTINCT ?t ?value ?valueLabel ?rrLabel ?rr (SAMPLE(?image) as ?img)
WHERE
{
VALUES ?person {wd:[entity:Robert Louis Stevenson]}
{?person wdt:[property:date of death] ?death .
?person ?prop ?t FILTER (datatype(?t)=xsd:dateTime) FILTER (?t <= ?death) .
?value wikibase:directClaim ?prop. }
UNION
{
?person ?q ?statement FILTER regex (STR(?q),"prop/P") . #exclude P:describedBy
?person wdt:[property:date of death] ?death .
?statement ?p ?t FILTER regex (STR(?p), "prop/qualifier/P") FILTER (datatype(?t)=xsd:dateTime) FILTER (?t <= ?death).
?statement ?r ?value FILTER regex (STR(?r),"prop/statement/") .
BIND(IRI(CONCAT(CONCAT(SUBSTR(STR(?r),1,29),"direct/"),SUBSTR(STR(?r),40))) as ?rprop)
?rr wikibase:directClaim ?rprop .
OPTIONAL {?value wdt:[property:image] ?image}
}
UNION { # author of / creator of
?value wdt:[property:author]|wdt:[property:editor]|wdt:[property:translator]|wdt:[property:P1773]|wdt:[property:creator] ?person .
?person wdt:[property:date of death] ?death .
?value wdt:[property:inception]|wdt:[property:publication date] ?t .
FILTER (?t <= ?death)
#FILTER NOT EXISTS {?value wdt:[property:edition or translation of] ?x }
FILTER NOT EXISTS {?person wdt:[property:notable work] ?value } .
OPTIONAL {?value wdt:[property:published in] ?rr .}
OPTIONAL {?value wdt:[property:image] ?image .}
}
UNION #Notable Works
{
?person wdt:[property:notable work] ?rr ;
wdt:[property:date of death] ?death ;
wdt:[property:date of birth] ?birth .
?rr wdt:[property:publication date]|wdt:[property:inception]|wdt:[property:date of first performance] ?t FILTER ((?t <= ?death)&&(?t >= ?birth)).
OPTIONAL {?rr wdt:[property:image] ?image .}
}
UNION #discoverer or inventor
{
?rr wdt:[property:discoverer or inventor] ?person .
?person wdt:[property:date of death] ?death ;
wdt:[property:date of birth] ?birth .
?rr wdt:[property:time of discovery or invention]|wdt:[property:inception]|wdt:[property:point in time] ?t FILTER ((?t <= ?death)&&(?t >= ?birth)).
OPTIONAL {?rr wdt:[property:image] ?image .}
}
UNION #architect
{
?rr wdt:[property:architect] ?person .
?person wdt:[property:date of death] ?death ;
wdt:[property:date of birth] ?birth .
?rr wdt:[property:inception]|wdt:[property:date of official opening] ?t FILTER ((?t <= ?death)&&(?t >= ?birth)).
OPTIONAL {?rr wdt:[property:image] ?image .}
}
UNION #composer
{
?rr wdt:[property:composer] ?person .
?person wdt:[property:date of death] ?death ;
wdt:[property:date of birth] ?birth .
?rr wdt:[property:inception]|wdt:[property:date of first performance]|wdt:[property:publication date] ?t FILTER ((?t <= ?death)&&(?t >= ?birth)).
OPTIONAL {?rr wdt:[property:image] ?image .}
}
SERVICE wikibase:label { bd:serviceParam wikibase:language "en, fr, de". }
} GROUP BY ?t ?value ?rr ?rrLabel ?valueLabel
ORDER BY ?t

